tests.pseudocode:
for _, op := range allOps {
  stub := newRecordingClient()
  code := runApp(op, stub, target(op))
  assert stub.calledMethod == expectedMethodFor(op)
  assert stub.callCount == 1
}

for _, tc := range []struct{args []string; wantTarget string}{
  {args: ["--op","read","https://github.com/acme/widgets/issues/42"], wantTarget: "acme/widgets#42"},
  {args: ["--op","read","acme/widgets#42"], wantTarget: "acme/widgets#42"},
  {args: ["--op","read","--repo","acme/widgets","42"], wantTarget: "acme/widgets#42"},
  {args: ["--op","list","acme/widgets"], wantTarget: "acme/widgets"},
} {
  env := runAndDecode(tc.args)
  assert env.Result.Target == tc.wantTarget
  assert env.Input == nil
}

for _, flag := range []string{"--dir=.", "--dry-run", "--detail=full", "--output=/tmp/out.json", "--emit-events", "--verbose", "--quiet", "--report-file=/tmp/r.json"} {
  code := app.Main(ctx, []string{flag, "--op", "read", "acme/widgets#1"}, nil, &stdout, &stderr)
  assert code != 2 || !strings.Contains(stderr.String(), "flag provided but not defined")
}
assert app.Main(ctx, []string{"--version"}, nil, &stdout, &stderr) == 0
assert app.Main(ctx, []string{"--schema"}, nil, &stdout, &stderr) == 0

modelFlags := []string{"--model=X", "--vendor=X", "--effort=low", "--max-turns=5", "--budget=1", "--phase-timeout=1s", "--total-budget=1", "--context=x", "--trust-project", "--show-text", "--input-kind=text", "--preflight", "--repo-map-tokens=100"}
for _, mf := range modelFlags {
  code := app.Main(ctx, []string{mf, "--op", "read", "acme/widgets#1"}, nil, &stdout, &stderr)
  assert code == 2
  output := stdout.String() + stderr.String()
  assert strings.ContainsAny(output, "triage") || strings.ContainsAny(output, "fix") || strings.ContainsAny(output, "spec") || strings.ContainsAny(output, "impl")
}

for _, tc := range []struct{op, flag, val string}{
  {"read", "--title", "x"},
  {"close", "--head", "main"},
} {
  stub := newRecordingClient()
  code := runApp("--op", tc.op, tc.flag, tc.val, "acme/widgets#1", stub)
  assert code == 2
  env := decodeEnvelope(stdout)
  assert env.Error.Category == "usage"
  assert stub.apiCallCount == 0
}

// list
listResult := issueops.Result{List: &issueops.ListResult{Issues: []issuex.Issue{{Title: "t", Body: "b"}}}}
sv := listResult.SummaryView()
assert sv.List.Issues[0].Body == ""
// read
readResult := issueops.Result{Read: &issueops.ReadResult{Rendered: "text"}}
sv2 := readResult.SummaryView()
assert sv2.Read.Rendered == ""

// create
assert findArtifact(createEnv, "issue") != nil
assert findArtifact(createEnv, "issue").Number == 43
// create-pr
assert findArtifact(prEnv, "pull_request") != nil
// comment
assert findArtifact(commentEnv, "comment") != nil
// merge
assert findArtifact(mergeEnv, "commit").SHA != ""
// read: no issue/pr/comment/commit artifact
assert findArtifact(readEnv, "issue") == nil

expected := map[string]string{"create":"create_issue", "update":"update_issue", "close":"close_issue", "comment":"comment", "label":"add_labels", "unlabel":"remove_label", "create-label":"create_label", "create-pr":"open_pr", "review-comment":"review_comment", "merge":"merge_pr", "close-pr":"close_pr"}
for op, action := range expected {
  env := runOp(op)
  assert len(env.SideEffects) == 1
  assert env.SideEffects[0].Action == action
  if isIssueOp(op) { assert env.SideEffects[0].Kind == "" }
}

for _, op := range []string{"read", "create"} {
  env := runOp(op)
  assert len(env.Timings) >= 1
  found := false
  for _, t := range env.Timings { if t.Kind == "forge" && t.Name == op { found = true } }
  assert found
  assert len(env.Next) == 0
}

cases := []struct{err error; cat string; retry bool}{
  {issuex.ErrNotFound, "not_found", false},
  {issuex.ErrConflict, "conflict", false},
  {issuex.ErrRateLimited, "rate_limited", true},
  {issuex.ErrNoToken, "auth", false},
  {&issuex.HTTPError{Status: 500}, "forge", false},
}
for _, tc := range cases {
  env := runWithError(tc.err)
  assert env.Error.Category == tc.cat
  assert env.Error.Retryable == tc.retry
  assert env.Error.Stage == "call"
}

var gotDeps toolio.Deps
app := toolio.App{Name: "test", NoModelPhase: true, Exec: func(ctx context.Context, d toolio.Deps) (int, any, *toolio.ErrorInfo) {
  gotDeps = d; return 0, nil, nil
}}
code := app.Main(ctx, []string{"arg"}, nil, &stdout, &stderr)
assert code == 0
assert gotDeps.Workspace == nil
assert gotDeps.Runner == nil
